    // `paths` is evaluated separately, rule by rule (below): it packs many independently governed rules into
    // one list, so the generic whole-leaf substitution this call does for every other key would be wrong for it.
    let mut v = crate::policy_precedence::evaluate_overlay(
        prec.as_ref(),
        "REPOSITORY_CONTRACT",
        "REPOSITORY_CONTRACT.yaml",
        &repository_contract_doc,
        &repository_contract_kernel,
        &["paths"],
    );
    let paths_source = "REPOSITORY_CONTRACT.yaml";
    let paths_new = repository_contract_doc
        .get("paths")
        .cloned()
        .unwrap_or(json!([]));
    // P2-HO-0056 §3 / OD-P2-08 §2 (Property C, precondition P1): the floor `evaluate_path_rules_overlay` checks
    // against is the kernel template's OWN `paths` UNIONED with this project's authenticated adoption floor --
    // the native-layout rules `gov init`/`gov adopt` derived from this repository's actual structure at
    // onboarding, which the kernel template (generic across every project) cannot itself name. A floor file that
    // exists but fails its T2 seal contributes NOTHING (never trusted anyway) and is surfaced as a refused
    // override through the same channel `gov policy overrides`/doctor D027 already reports, rather than being
    // silently ignored (OC-P2-04 §4).
    let adoption_floor = crate::paths::read_project_adoption_floor(root);
    if let Some(finding) = &adoption_floor.finding {
        ps.refused_overrides.push(finding.clone());
    }
    // P2-AR-0093 (AR92-C4): a non-refusing disclosure -- separate channel, see `floor_disclosures`'s own doc.
    if let Some(disclosure) = &adoption_floor.bootstrap_disclosure {
        ps.floor_disclosures.push(disclosure.clone());
    }
    // AR82-C2 (P2-AR-0082, fail-safe not fail-open): `read_project_adoption_floor`'s own doc calls an ABSENT
    // floor file "a legitimate, unflagged state" -- true for a project never onboarded through the mechanism,
    // but indistinguishable, by that check alone, from a project whose floor file was simply deleted (an
    // ordinary `rm`/`mv`), which OD-P2-08 §2/§4 forbid: "ordinary edits must not silently remove obligations
    // established by the authenticated floor". Measured end to end: delete the floor, widen a previously
    // floored pattern, and nothing anywhere reports it.
    //
    // The repair does not try to distinguish "never onboarded" from "onboarded then deleted" -- that is not
    // decidable from this file alone, and OD-P2-08 §2's own algorithm ("inventory X's NATIVE structure ->
    // derive the proposed Project-X floor") gives a cheaper answer that does not need the distinction: when the
    // AUTHENTICATED floor is empty, re-derive what a FRESH onboarding would floor TODAY, from this
    // repository's own current native structure, by calling the exact same function `gov init` itself calls
    // ([`crate::init::native_layout_rules`] -- reused, not re-implemented, so there is exactly one definition
    // of "what native-layout rules does this repository need"). Use that reconstruction as the effective floor
    // for THIS load (so an ordinary widening of a native pattern is still refused even with no authenticated
    // record backing it) and disclose that it happened (OC-P2-04 §4, "silence is failure"; this also gives
    // `gov doctor`'s D027 -- which already reports every entry `refused_overrides` carries, the same channel
    // the broken-seal finding above already uses -- something to say, closing the reviewer's separate
    // complaint that no doctor check mentioned the missing floor). A bare project whose current structure
    // derives NO native-layout rules at all is genuinely unaffected (the empty-floor no-op
    // [`crate::paths::write_project_adoption_floor`] itself documents) -- the reconstruction is only attempted,
    // and only reported, when there is something concrete to reconstruct.
    //
    // **AR84-C3.** Originally gated on `adoption_floor.finding.is_none()` too -- i.e. reconstruction fired only
    // for an ABSENT floor file, never for one that exists but is not honoured (a broken T2 seal, or -- AR84-C3 --
    // one bound to a DIFFERENT repository). That left exactly the gap AR84-C3 measured: a foreign floor is
    // rejected (`finding` is `Some`), `floor_rules` is correctly empty, but reconstruction never ran, so
    // `src/**` (a native-layout pattern the KERNEL TEMPLATE itself does not know) was governed by NOTHING and a
    // widening of it was silently honoured. The condition is now simply "no rules to protect with", whatever
    // the reason -- the finding above (if any) already discloses WHY the authenticated record isn't trusted;
    // reconstruction is the same fail-safe response to "no trustworthy floor" regardless of cause.
    let mut floor_rules = adoption_floor.rules.clone();
    if floor_rules.is_empty() {
        let mut reconstructed = crate::init::native_layout_rules(root);
        let fresh_patterns: std::collections::BTreeSet<String> = reconstructed
            .iter()
            .filter_map(|r| r.get("pattern").and_then(|v| v.as_str()).map(str::to_string))
            .collect();
        // AR86-C6: a reconstruction derived from the repository's CURRENT on-disk shape can be made narrower
        // than an authenticated floor it replaces by an ordinary rearrangement (moving a directory's code
        // under an `ALWAYS_EXCLUDED_DIRS` name, without deleting anything) -- nothing a person would call
        // "gone", but enough to make `native_layout_rules`'s own `has_code` check miss it. Union in this
        // CHECKOUT's own last-known-authenticated rule set (`crate::paths::last_known_adoption_floor_rules`,
        // kept outside every repository-tracked file the SAME rearrangement could touch) for any pattern the
        // fresh derivation does not already cover, so a reconstruction is never weaker than what this checkout
        // last saw proof-grade.
        let mut shrunk: Vec<String> = vec![];
        for r in crate::paths::last_known_adoption_floor_rules(root) {
            if let Some(p) = r.get("pattern").and_then(|v| v.as_str()) {
                if !fresh_patterns.contains(p) {
                    shrunk.push(p.to_string());
                    reconstructed.push(r);
                }
            }
        }
        if !reconstructed.is_empty() {
            let patterns: Vec<String> = reconstructed
                .iter()
                .filter_map(|r| r.get("pattern").and_then(|v| v.as_str()).map(str::to_string))
                .collect();
            let shrinkage = if shrunk.is_empty() {
                String::new()
            } else {
                format!(
                    " (the fresh derivation alone would have missed {shrunk:?} -- restored from this \
                     checkout's own record of the last authenticated floor)"
                )
            };
            ps.refused_overrides.push(json!({
                "policy": "PROJECT_ADOPTION_FLOOR", "key": "floor", "value": Value::Null,
                "source": crate::paths::PROJECT_ADOPTION_FLOOR_PATH, "kernel_value": Value::Null,
                "reason": format!(
                    "{} carries no trustworthy authenticated floor for this repository right now (absent, an \
                     unverified seal, or bound to a different repository -- see any other PROJECT_ADOPTION_FLOOR \
                     finding above for which), but this repository's own current native-layout structure would \
                     derive a floor covering {patterns:?}{shrinkage} -- unauthenticated, so this load protects \
                     them by RECONSTRUCTING that floor from disk rather than trusting nothing; the authenticated \
                     record itself must be restored from version control or re-derived through a fresh governed \
                     onboarding transaction (`gov init`/`gov adopt`) before this project's floor is proof-grade \
                     again (OD-P2-08 §2/§4/§5, P2-AR-0082 AR82-C2, AR84-C1/AR84-C3, AR86-C6)",
                    crate::paths::PROJECT_ADOPTION_FLOOR_PATH
                ),
            }));
            floor_rules = reconstructed;
        }
    }
    let paths_kernel = {
        let mut arr = repository_contract_kernel("paths")
            .and_then(|v| v.as_array().cloned())
            .unwrap_or_default();
        arr.extend(floor_rules.clone());
        (!arr.is_empty()).then(|| json!(arr))
    };
    let pv = match &prec {
        Some(_) => crate::policy_precedence::evaluate_path_rules_overlay(
            paths_kernel.as_ref(),
            &paths_new,
            "REPOSITORY_CONTRACT",
            paths_source,
        ),
        None => {
            let mut d = crate::policy_precedence::OverlayVerdict::default();
            d.effective = paths_kernel.clone().unwrap_or(json!([]));
            d.refused.push(json!({"policy": "REPOSITORY_CONTRACT", "key": "paths", "value": paths_new,
                "source": paths_source, "kernel_value": paths_kernel, "reason": "REPOSITORY_CONTRACT.paths: precedence rules unavailable (fail closed)"}));
            d
        }
    };
    crate::util::deep_set(&mut v.effective, "paths", pv.effective);
    ps.applied_overrides.extend(v.applied);
    ps.applied_overrides.extend(pv.applied);
    ps.refused_overrides.extend(v.refused);
    ps.refused_overrides.extend(pv.refused);
    ps.effective_overlays
        .insert("REPOSITORY_CONTRACT.yaml".into(), v.effective.clone());
    overlay.set_effective("REPOSITORY_CONTRACT.yaml", v.effective);

    let data_sensitivity_template = read_yaml(
        &kernel_dir
            .join("overlay-templates")
            .join("DATA_SENSITIVITY.yaml"),
    )
    .unwrap_or(json!({}));
    let data_sensitivity_kernel =
        |dotted: &str| deep_get(&data_sensitivity_template, dotted).cloned();
    let data_sensitivity_doc = overlay.get("DATA_SENSITIVITY.yaml");
    // `classifications` is evaluated separately, entry by entry (below): like `paths`, it packs independently
    // governed, pattern-keyed declarations into one list, so the generic whole-leaf substitution this call does
    // for every other key would discard every classification the project declared on refusing just one.
    let mut v = crate::policy_precedence::evaluate_overlay(
        prec.as_ref(),
        "DATA_SENSITIVITY",
        "DATA_SENSITIVITY.yaml",
        &data_sensitivity_doc,
        &data_sensitivity_kernel,
        &["classifications"],
    );
    let ds_source = "DATA_SENSITIVITY.yaml";
    let classifications_new = data_sensitivity_doc
        .get("classifications")
        .cloned()
        .unwrap_or(json!([]));
    let classifications_kernel = data_sensitivity_kernel("classifications");
    let cv = match &prec {
        Some(_) => crate::policy_precedence::evaluate_classifications_overlay(
            classifications_kernel.as_ref(),
            &classifications_new,
            "DATA_SENSITIVITY",
            "classifications",
            ds_source,
        ),
        None => {
            let mut d = crate::policy_precedence::OverlayVerdict::default();
            d.effective = classifications_kernel.clone().unwrap_or(json!([]));
            d.refused.push(json!({"policy": "DATA_SENSITIVITY", "key": "classifications", "value": classifications_new,
                "source": ds_source, "kernel_value": classifications_kernel, "reason": "DATA_SENSITIVITY.classifications: precedence rules unavailable (fail closed)"}));
            d
        }
    };
    crate::util::deep_set(&mut v.effective, "classifications", cv.effective);
    ps.applied_overrides.extend(v.applied);
    ps.applied_overrides.extend(cv.applied);
    ps.refused_overrides.extend(v.refused);
    ps.refused_overrides.extend(cv.refused);
    ps.effective_overlays
        .insert("DATA_SENSITIVITY.yaml".into(), v.effective.clone());
    overlay.set_effective("DATA_SENSITIVITY.yaml", v.effective);
    ps
}
pub fn policy(&self, name: &str) -> Result<&Value> {
    self.effective
